"""Generated by the QA agent for STORY-104: Send money to a beneficiary within my daily limit."""
from playwright.sync_api import expect


def send_ui(page, amount):
    page.goto("/transfer")
    page.get_by_test_id("transfer-from").select_option("SAV-1002")
    page.get_by_test_id("transfer-to").select_option("ben:1")
    page.get_by_test_id("transfer-amount-input").fill(str(amount))
    page.get_by_test_id("transfer-send").click()


def test_tc_104_01_beneficiary_transfer_succeeds_ui(signed_in, amira):
    """TC-104-01 (UI)"""
    send_ui(signed_in, "1500.00")
    expect(signed_in.get_by_test_id("transfer-success")).to_contain_text("Transfer completed")
    assert amira.balance("SAV-1002") == 98500.00


def test_tc_104_02_daily_limit_is_cumulative_api(amira):
    """TC-104-02 (API)"""
    body = {"from_account": "SAV-1002", "beneficiary_id": 1, "amount": 30000}
    first = amira.post("/api/transfers", json=body)
    assert first.status_code == 201, first.text
    second = amira.post("/api/transfers", json=body)
    assert second.status_code == 409, (f"second EGP 30,000 transfer on the same day should exceed the EGP 50,000 "
                                       f"daily limit, got {second.status_code}: {second.text}")


def test_tc_104_03_single_transfer_above_limit_refused_api(amira):
    """TC-104-03 (API)"""
    r = amira.post("/api/transfers", json={"from_account": "SAV-1002", "beneficiary_id": 1, "amount": 50000.01})
    assert r.status_code == 409, r.text
    assert amira.balance("SAV-1002") == 100000.00


def test_tc_104_04_limit_message_and_no_money_moved_ui(signed_in, amira):
    """TC-104-04 (UI)"""
    page = signed_in
    for _ in range(2):
        page.goto("/transfer")
        page.get_by_test_id("transfer-from").select_option("SAV-1002")
        page.get_by_test_id("transfer-to").select_option("ben:1")
        page.get_by_test_id("transfer-amount-input").fill("30000")
        page.get_by_test_id("transfer-submit").click()
    expect(page.get_by_test_id("transfer-error")).to_contain_text("daily limit")
    assert amira.balance("SAV-1002") == 70000.00
